def solve(g):
    g = g.copy()
    lab,_ = ndimage.label(g!=0)
    out = g.copy()
    marker = {}
    for c in np.unique(g):
        if c not in (0,1):
            ys,xs = np.where(g==c)
            for y,x in zip(ys,xs): marker[lab[y,x]] = c
    H,W = g.shape
    for r in range(H):
        for c in range(W):
            if g[r,c]==1:
                if r>0 and r<H-1 and c>0 and c<W-1 and g[r-1,c]!=0 and g[r+1,c]!=0 and g[r,c-1]!=0 and g[r,c+1]!=0:
                    out[r,c] = marker[lab[r,c]]
    return out

